def flatten_dict(d):
    result = {}
    for key, value in d.items():
        new_key = f"{key}." if isinstance(value, dict) else key
        if isinstance(value, dict):
            if value:
                sub = flatten_dict(value)
                for sub_key, sub_value in sub.items():
                    result[f"{key}.{sub_key}"] = sub_value
            # Empty dict contributes nothing
        else:
            result[key] = value
    return result
